package com.mahesh.empleave.dashboard;import com.mahesh.empleave.leave.*;import com.mahesh.empleave.user.*;import lombok.*;import org.springframework.security.access.prepost.*;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/dashboard") @RequiredArgsConstructor public class DashboardController{private final LeaveRepository leaves;private final UserRepository users;record EmployeeDashboard(long myRequests,long pending,long approved){}record ManagerDashboard(long teamPending,long teamRequests){}record AdminDashboard(long employees,long totalRequests,long pending){}@GetMapping("/employee") @PreAuthorize("hasAnyRole('EMPLOYEE','MANAGER','ADMIN')") EmployeeDashboard employee(Authentication a){var u=users.findByEmail(a.getName()).orElseThrow();var mine=leaves.findByApplicantOrderByIdDesc(u);return new EmployeeDashboard(mine.size(),mine.stream().filter(x->x.getStatus()==LeaveStatus.PENDING).count(),mine.stream().filter(x->x.getStatus()==LeaveStatus.APPROVED).count());}@GetMapping("/manager") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") ManagerDashboard manager(Authentication a){var u=users.findByEmail(a.getName()).orElseThrow();var team=leaves.findAll().stream().filter(x->x.getApplicant().getManager()!=null&&x.getApplicant().getManager().getId().equals(u.getId())).toList();return new ManagerDashboard(team.stream().filter(x->x.getStatus()==LeaveStatus.PENDING).count(),team.size());}@GetMapping("/admin") @PreAuthorize("hasRole('ADMIN')") AdminDashboard admin(){var all=leaves.findAll();return new AdminDashboard(users.count(),all.size(),all.stream().filter(x->x.getStatus()==LeaveStatus.PENDING).count());}}
